param([string]$BaseUrl = "http://localhost:3000")
$ErrorActionPreference = "Stop"; $root = Split-Path -Parent $PSScriptRoot; Set-Location $root
function Assert-FileExists { param([string]$Path) if (-not (Test-Path $Path)) { throw "[FAIL] Missing file: $Path" } Write-Host "[PASS] file exists: $Path" }
function Assert-DirectoryExists { param([string]$Path) if (-not (Test-Path $Path -PathType Container)) { throw "[FAIL] Missing directory: $Path" } Write-Host "[PASS] directory exists: $Path" }
function Assert-Contains { param([AllowEmptyString()][string]$Haystack,[string]$Needle,[string]$Name) if (-not $Haystack.Contains($Needle)) { throw "[FAIL] Missing $Name`: $Needle" } Write-Host "[PASS] $Name" }
function Assert-NotMatches { param([AllowEmptyString()][string]$Haystack,[string]$Pattern,[string]$Name) if ($Haystack -match $Pattern) { throw "[FAIL] Unexpected $Name`: $Pattern" } Write-Host "[PASS] $Name" }
function Assert-CountExactly { param([AllowEmptyString()][string]$Haystack,[string]$Needle,[int]$Expected,[string]$Name) $count=([regex]::Matches($Haystack,[regex]::Escape($Needle))).Count; if($count -ne $Expected){throw "[FAIL] $Name expected $Expected found $count"} Write-Host "[PASS] $Name" }
Write-Host "=== CodexForge Validation Result Capture MVP smoke ==="
$domainDir="src\lib\codexforge\validation-result-capture-mvp"; $componentDir=Join-Path $domainDir "components"; $routePath="src\app\validation-results\page.tsx"; $clientPath="src\app\validation-results\page-client.tsx"
Assert-DirectoryExists $domainDir; Assert-DirectoryExists $componentDir
foreach($module in @("validation-result-capture-types.ts","validation-capture-input.ts","validation-command-capture.ts","validation-output-parser.ts","validation-pass-fail-summary.ts","validation-failure-routing.ts","validation-result-handoff.ts","validation-result-export.ts","validation-result-next-action.ts","validation-result-capture-summary.ts","index.ts")){Assert-FileExists (Join-Path $domainDir $module)}
foreach($component in @("ValidationResultCapturePanel.tsx","ValidationCaptureInputPanel.tsx","ValidationCommandCapturePanel.tsx","ValidationOutputParserPanel.tsx","ValidationPassFailSummaryPanel.tsx","ValidationFailureRoutingPanel.tsx","ValidationResultHandoffPanel.tsx","ValidationResultExportPanel.tsx","ValidationResultNextActionPanel.tsx","ValidationResultSafetyStrip.tsx","ValidationResultEmptyState.tsx")){Assert-FileExists (Join-Path $componentDir $component)}
Assert-FileExists $routePath; Assert-FileExists $clientPath
$indexSource=Get-Content -Raw (Join-Path $domainDir "index.ts"); $domainSource=(Get-ChildItem $domainDir -File|%{Get-Content -Raw $_.FullName}) -join "`n"; $uiSource=(Get-ChildItem $componentDir -File|%{Get-Content -Raw $_.FullName}) -join "`n"; $routeSource=(Get-Content -Raw $routePath)+"`n"+(Get-Content -Raw $clientPath); $allSource=$domainSource+"`n"+$uiSource+"`n"+$routeSource
foreach($export in @("buildValidationCaptureInput","validateValidationCaptureInput","buildValidationCommandCapture","buildValidationOutputParser","parseValidationOutputSummary","buildValidationPassFailSummary","buildValidationFailureRouting","buildValidationResultHandoff","buildValidationResultExport","selectValidationResultNextAction","buildValidationResultCaptureSummary")){Assert-Contains $indexSource $export "index exports $export"}
foreach($render in @("ValidationResultCapturePanel renders","ValidationCaptureInputPanel renders","ValidationCommandCapturePanel renders","ValidationOutputParserPanel renders","ValidationPassFailSummaryPanel renders","ValidationFailureRoutingPanel renders","ValidationResultHandoffPanel renders","ValidationResultExportPanel renders","ValidationResultNextActionPanel renders","ValidationResultSafetyStrip renders","ValidationResultEmptyState renders")){Assert-Contains $uiSource $render $render}
foreach($text in @("Capture validation result","Review validation output","Paste validation output to review the result.","command list","manually supplied output","exit code","pass/fail/unknown","detected error lines","detected warnings","truncated output flag","failure routes to /closed-loop","passing routes to /workflow-results and /run-history","git diff check failure routes to /apply-validation or /files","no command execution","no auto-run","no fabricated output","cap output","preserve latest-message authority","Focus Mode UX calm workflow layout markers","shell without duplicate route chip cloud","route hero title does not vertically wrap","no giant raw JSON above fold","advanced details are collapsed or visually secondary","no unsafe execution buttons","buildValidationResultStableKey")){Assert-Contains $allSource $text "marker $text"}
Assert-Contains $routeSource "ValidationResultCapturePanel" "route imports/renders main panel"
foreach($bad in @("appendEvent\s*\(","saveBrainGraph\s*\(","\.nodes\s*\.\s*push|\.edges\s*\.\s*push","apply-diff\s*\(","write-file\s*\(","run-command\s*\(","broker-execution\s*\(","https?://","fetch\s*\(","OPENAI_API_KEY","localStorage.setItem","process\.env\.","Math\.random","Date\.now","d3-force","[\u00c3\u00c2]")){Assert-NotMatches $allSource $bad "blocked marker absent $bad"}
Assert-Contains ((Get-Content -Raw "src\app\validation\page-client.tsx")+(Get-Content -Raw "src\app\apply-validation\page-client.tsx")+(Get-Content -Raw "src\app\workflow-results\page-client.tsx")+(Get-Content -Raw "src\app\closed-loop\page.tsx")) "/validation-results" "integrations mention validation results"
Assert-CountExactly (Get-Content -Raw "scripts\smoke-codexforge-all.ps1") "smoke-codexforge-validation-result-capture-mvp.ps1" 1 "managed smoke suite includes phase exactly once"
Write-Host "[OK] CodexForge Validation Result Capture MVP smoke passed."
